// ════════════════════════════════════════════════════════════════════════════
//  Axon ASI flagship: an autonomous Meta-Ads optimizer.
// ════════════════════════════════════════════════════════════════════════════
//
//  A real campaign-management problem, with every Axon ASI primitive doing the
//  job it was designed for — not as separate demos, but woven into one agent:
//
//    * @[goal(strategy: tournament)]  — search a large space of ad variants
//      (audience × creative) to maximize predicted ROAS. Tournament beats a
//      hill-climb here because the ROAS landscape is multi-modal (several
//      audience pockets convert well).
//    * Uncertain<T>                   — every ROAS prediction carries the
//      model's CONFIDENCE. A high score we're unsure about is not the same as
//      a high score we trust.
//    * Temporal<T>                    — ad creative FATIGUES. A winner today is
//      worth less in a week; confidence in the creative decays per day, so the
//      agent knows when to refresh.
//    * @[verify(value <= cap)]        — a hard SAFETY bound the compiler proves:
//      the recommended daily spend can never exceed the budget cap.
//    * agent metacognition            — the agent inspects its own search trace
//      to decide whether it has CONVERGED or is spinning its wheels.
//
//  Run:  AXON_SEED=42 axon run examples/asi/ad_optimizer.ax
//
//  (Deterministic under AXON_SEED — no API key, no network: the "predicted
//  ROAS" model is a stand-in for a live ai_extract call, so the demo is a
//  reproducible showcase of the control flow.)

// ── 1. The ad-performance model ─────────────────────────────────────────────
// A variant id encodes an (audience segment × creative) pair. In production
// this score comes from `ai_extract_uncertain_i64("predict ROAS for …")`; here
// it's a deterministic multi-modal landscape so the demo is reproducible. ROAS
// is return-on-ad-spend ×100 (so 320 = 3.2x).
@[adaptive]
fn variant_roas(v: i64) -> i64 {
    // Two converting pockets (a broad audience near v=37, a niche near v=78);
    // the broad pocket pays better. Everything else is mediocre.
    let broad = 320 - ((v - 37) * (v - 37)) / 8
    let niche = 260 - ((v - 78) * (v - 78)) / 4
    if broad > niche { broad } else { niche }
}

// ── 2. The optimizer: search variants with the tournament strategy ──────────
// The target is a STRETCH ROAS (3.5x = 350) — higher than any single variant
// can hit (the best pocket caps near 3.2x). So the agent searches the full
// budget and converges on the best ACHIEVABLE variant rather than stopping at
// the first "good enough", which is exactly how you run a real campaign.
@[goal(metric: variant_roas, target: 350, strategy: tournament, lo: 0, hi: 100, max_evals: 80)]
fn optimize_campaign() -> i64 {
    // Met if we cleared a realistic 3.0x floor (300), even if the 3.5x stretch
    // target isn't reachable.
    let best = goal_best_score("variant_roas", 350.0)
    if f64_to_i64(best) >= 300 { 1 } else { 0 }
}

// ── 3. A ROAS prediction with confidence (Uncertain<T>) ─────────────────────
// The score's trustworthiness scales with how strong it is — a marginal
// improvement is reported with lower confidence than a clear winner.
fn roas_with_confidence(score: i64) -> Uncertain<i64> {
    let conf_pts = if score >= 300 { 92 } else if score >= 240 { 78 } else { 55 }
    uncertain_dyn_i64(score, i64_to_f64(conf_pts) / 100.0)
}

// ── 4. A spend recommendation with a compiler-ENFORCED safety bound ─────────
// @[verify] is a hard bound: this function can never return a spend above the
// $500/day cap, no matter the predicted ROAS. The runtime gate enforces it on
// every call (a breach is a policy rejection, exit 3 — not a silent overspend).
// A pure-arithmetic verify body can ALSO be proven statically by `axon verify`
// (the Z3 path); this one returns an Uncertain so it uses the runtime gate.
@[verify(value <= 500)]
fn recommend_spend(predicted_roas: i64) -> Uncertain<i64> {
    // Spend a fraction of predicted ROAS, hard-capped at the daily budget.
    let raw = predicted_roas + 100
    let safe = if raw > 500 { 500 } else { raw }
    uncertain_dyn_i64(safe, 0.9)
}

fn main() -> i64 {
    println("── Meta-Ads autonomous optimizer ───────────────────────────────")

    // Step 1: search the variant space (tournament over audience × creative).
    let met = optimize_campaign()
    let best_variant = goal_best_input("variant_roas", 350.0)
    let best_score = f64_to_i64(goal_best_score("variant_roas", 350.0))
    let evaluated = agent_trace_len("variant_roas")
    println("searched {to_str(evaluated)} variants → best variant #{to_str(best_variant)}")

    // Step 2: report the winning ROAS WITH confidence.
    let prediction = roas_with_confidence(best_score)
    println("predicted ROAS {to_str(prediction.value)} (3.2x) @ confidence {to_str_f64(prediction.confidence)}")

    // Step 3: metacognition — did the search converge, or is it stuck?
    if agent_detect_loop("variant_roas") {
        println("metacog: search has converged (no further progress)")
    } else {
        println("metacog: search uncertainty {to_str_f64(agent_uncertainty(\"variant_roas\"))} — explored broadly")
    }

    // Step 4: a PROVABLY-SAFE spend recommendation (never exceeds the cap).
    let spend = recommend_spend(best_score)
    println("recommended spend ${to_str(spend.value)}/day (compiler-capped at 500)")

    // Step 5: ad fatigue — the winning creative decays. Plan the refresh.
    let day = 86400000
    let creative = temporal_new(best_score, 14 * day, 0.08)
    let in_7d = temporal_at(creative, 7 * day)
    println("creative fatigue: trust 1.0 today → {to_str_f64(in_7d.confidence)} in 7 days")
    if temporal_confidence(in_7d) < 0.6 {
        println("action: schedule a creative refresh within the week")
    }

    println("─────────────────────────────────────────────────────────────────")
    if met == 1 { 0 } else { 1 }
}

@[test]
fn test_variant_roas_pocket_peaks() {
    assert_eq(variant_roas(37), 320)
    assert_eq(variant_roas(78), 260)
    assert_eq(variant_roas(45), 312)
    assert_eq(variant_roas(29), 312)
}

@[test]
fn test_variant_roas_edges() {
    assert_eq(variant_roas(0), 149)
    assert_eq(variant_roas(100), 139)
    assert_eq(variant_roas(60), 254)
    assert_eq(variant_roas(80), 259)
}

@[test]
fn test_variant_roas_best_pocket_below_stretch() {
    let best = -1000000
    for v in 0..101 {
        let r = variant_roas(v)
        if r > best { best = r }
    }
    assert_eq(best, 320)
    assert_eq(variant_roas(36), 320)
    assert_eq(variant_roas(38), 320)
    assert_eq(variant_roas(34), 319)
    assert(best < 350)
    assert(best >= 300)
}

@[test]
fn test_roas_with_confidence_tiers() {
    let hi = roas_with_confidence(300)
    assert_eq(hi.value, 300)
    assert(abs_f64(hi.confidence - 0.92) < 0.000001)
    let mid = roas_with_confidence(299)
    assert_eq(mid.value, 299)
    assert(abs_f64(mid.confidence - 0.78) < 0.000001)
    let mid2 = roas_with_confidence(240)
    assert(abs_f64(mid2.confidence - 0.78) < 0.000001)
    let lo = roas_with_confidence(239)
    assert_eq(lo.value, 239)
    assert(abs_f64(lo.confidence - 0.55) < 0.000001)
}

@[test]
fn test_roas_with_confidence_of_variants() {
    let top = roas_with_confidence(variant_roas(37))
    assert_eq(top.value, 320)
    assert(abs_f64(top.confidence - 0.92) < 0.000001)
    let niche = roas_with_confidence(variant_roas(78))
    assert_eq(niche.value, 260)
    assert(abs_f64(niche.confidence - 0.78) < 0.000001)
    let weak = roas_with_confidence(0)
    assert_eq(weak.value, 0)
    assert(abs_f64(weak.confidence - 0.55) < 0.000001)
}

@[test]
fn test_recommend_spend_below_cap() {
    let s = recommend_spend(0)
    assert_eq(s.value, 100)
    assert(abs_f64(s.confidence - 0.9) < 0.000001)
    assert_eq(recommend_spend(250).value, 350)
    assert_eq(recommend_spend(399).value, 499)
    assert_eq(recommend_spend(-50).value, 50)
}

@[test]
fn test_recommend_spend_capped_at_500() {
    assert_eq(recommend_spend(400).value, 500)
    assert_eq(recommend_spend(401).value, 500)
    assert_eq(recommend_spend(10000).value, 500)
    assert(abs_f64(recommend_spend(10000).confidence - 0.9) < 0.000001)
}

@[test]
fn test_recommend_spend_for_best_variant() {
    assert_eq(recommend_spend(variant_roas(37)).value, 420)
    assert_eq(recommend_spend(variant_roas(78)).value, 360)
}

// experiment_zone.ax — the Experiment code zone (R4)
//
// Axon has three code zones beyond plain Static code:
//   @[adaptive]        — the compiler logs every return AND feeds it to the
//                        optimizer (goal_run hill-climbs it). An optimization
//                        TARGET.
//   @[experiment(lbl)] — the compiler logs every return too (un-opt-out-able
//                        provenance, I-13), but the optimizer IGNORES it. A
//                        comparison BASELINE, never auto-promoted.
//   @[agent]           — highest trust; every action is audit-logged.
//
// Both adaptive and experiment leave a durable record in the provenance log
// (see `axon trace`), tagged with their zone. The difference is purely
// behavioral: only adaptive records steer goal_run.
//
// Run:   axon run examples/asi/experiment_zone.ax
// Then:  axon trace            # see both zones' records, tagged

// The optimization target: the compiler will hill-climb this toward a goal.
@[adaptive]
fn tuned(x: i64) -> i64 {
    100 - (x - 7) * (x - 7)      // a hill peaking at x = 7
}

// A fixed baseline we want to MEASURE against the tuned fn, but never optimize.
// It is logged (provenance), labelled "control", yet kept out of goal_run.
@[experiment("control")]
fn baseline(x: i64) -> i64 {
    50                            // a flat reference line
}

fn main() -> i64 {
    // Record a few baseline observations (these LOG but do not optimize).
    let _ = baseline(1)
    let _ = baseline(2)
    let _ = baseline(3)
    let base_in_store = goal_count("baseline")
    println("baseline in optimizer store: {to_str(base_in_store)} (expect 0)")

    // Optimize the adaptive fn toward 100. Only its records are in the store.
    let best = goal_run("tuned", 100.0, 40)
    let tuned_probes = goal_count("tuned")
    println("tuned best score: {to_str_f64(best)} (optimized toward 100)")
    println("tuned probes in store: {to_str(tuned_probes)}")

    // The experiment stayed a baseline: 0 probes drove the optimizer, even
    // though its returns are in the provenance log for `axon trace` to compare.
    base_in_store                 // => 0  (clean exit code)
}

@[test]
fn test_tuned_hill_peaks_at_7() {
    assert_eq(tuned(7), 100)
    assert_eq(tuned(6), 99)
    assert_eq(tuned(8), 99)
    assert_eq(tuned(4), 91)
    assert_eq(tuned(10), 91)
}

@[test]
fn test_tuned_far_values() {
    assert_eq(tuned(0), 51)
    assert_eq(tuned(17), 0)
    assert_eq(tuned(-3), 0)
    assert_eq(tuned(27), -300)
}

@[test]
fn test_baseline_is_flat_50() {
    assert_eq(baseline(1), 50)
    assert_eq(baseline(2), 50)
    assert_eq(baseline(3), 50)
    assert_eq(baseline(0), 50)
    assert_eq(baseline(-100), 50)
}

@[test]
fn test_baseline_versus_tuned() {
    assert_eq(baseline(7), 50)
    assert(tuned(7) > baseline(7))
    assert_eq(tuned(0) - baseline(0), 1)
    assert_eq(baseline(1000000), 50)
}

// risk_monitor.ax
//
// Risk-aware AI agent with self-monitoring compliance.
//
// Demonstrates:
//   Phase 11 Risk typing: risk derived from effect set + budget consumption
//   Pipeline gate: High/Critical risk → full simulate→stress→redteam→verify→deploy
//   Self-monitoring: agent checks its own compliance after each action
//   Self-halt: on policy violation, agent exits cleanly (not via panic)
//
// This shows what R29 does at the language level — the continuous compliance
// monitor is the compile-time + runtime realization of this pattern.

// ── Risk derivation ──────────────────────────────────────────────────────────
// effects: "AI"=pure, "Net"=medium, "Exec"=medium, "Net_Exec"=high
// risk: 0=Low, 1=Medium, 2=High, 3=Critical

fn agent_risk(effects: str, budget_burn_pct: i64, irreversible: bool) -> i64 {
    if irreversible { 3 }
    else if budget_burn_pct > 80 { 2 }
    else if str_eq(effects, "Net_Exec") { 2 }
    else if str_eq(effects, "Net") || str_eq(effects, "Exec") { 1 }
    else { 0 }
}

fn risk_name(r: i64) -> str {
    if r <= 0 { "Low" }
    else if r == 1 { "Medium" }
    else if r == 2 { "High" }
    else { "Critical" }
}

// ── Policy & compliance ──────────────────────────────────────────────────────

type Policy = { allowed_effects: str, max_budget_pct: i64 }

fn check_compliance(policy: Policy, actual_effects: str, budget_pct: i64) -> Result<str, str> {
    if budget_pct > policy.max_budget_pct {
        Err("budget exceeded: {to_str(budget_pct)}% > {to_str(policy.max_budget_pct)}%")
    } else if str_eq(actual_effects, "Net") && !str_contains(policy.allowed_effects, "Net") {
        Err("effect denied: Net not in allowed_effects={policy.allowed_effects}")
    } else if str_eq(actual_effects, "Exec") && !str_contains(policy.allowed_effects, "Exec") {
        Err("effect denied: Exec not in allowed_effects")
    } else {
        Ok("compliant")
    }
}

// ── Adaptive scorer ──────────────────────────────────────────────────────────

@[adaptive(metric: work_score, target: 100)]
fn score_work(effort: i64) -> i64 {
    if effort < 10 { effort * 9 }
    else if effort < 20 { 90 + (effort - 10) / 2 }
    else { 95 }
}

// ── Self-monitoring loop ─────────────────────────────────────────────────────
// Runs the agent up to 5 iterations, checking compliance after every action.
// On a policy violation the agent records the reason and breaks out of the
// loop — it self-halts before the next action, not after.

fn run_monitored(policy: Policy, total_budget: i64) -> Result<i64, str> {
    let spent = 0
    let best_score = 0
    let iteration = 0
    let violated = false
    let violation_reason = ""

    while iteration < 5 && spent < total_budget && !violated {
        let effort = iteration * 5
        let cost = 10
        spent = spent + cost
        let budget_pct = (spent * 100) / total_budget
        let actual_effects = "AI"

        match check_compliance(policy, actual_effects, budget_pct) {
            Ok(_) => {
                let score = score_work(effort)
                if score > best_score { best_score = score }
                println("  iter={to_str(iteration)} score={to_str(score)} budget={to_str(budget_pct)}%")
            }
            Err(reason) => {
                println("  COMPLIANCE VIOLATION: {reason}")
                println("  Agent self-halting (R29 pattern)")
                violated = true
                violation_reason = reason
            }
        }
        iteration = iteration + 1
    }

    if violated { Err(violation_reason) } else { Ok(best_score) }
}

// ── Risk-gated deploy ────────────────────────────────────────────────────────
// High/Critical risk requires the full pipeline; Low/Medium only needs verify.

fn gate_by_risk(risk: i64, score: i64) -> bool {
    if risk >= 2 {
        let simulate_ok = score > 50
        let stress_ok = score > 60
        let redteam_ok = score > 70
        let verify_ok = score > 80
        println("  [gate] simulate={to_str_bool(simulate_ok)} stress={to_str_bool(stress_ok)} redteam={to_str_bool(redteam_ok)} verify={to_str_bool(verify_ok)}")
        simulate_ok && stress_ok && redteam_ok && verify_ok
    } else {
        let verify_ok = score > 40
        println("  [gate] verify={to_str_bool(verify_ok)}")
        verify_ok
    }
}

// ── Tests ────────────────────────────────────────────────────────────────────

@[test]
fn test_risk_low_for_ai_only() { assert_eq(agent_risk("AI", 20, false), 0) }

@[test]
fn test_risk_high_for_net_exec() { assert_eq(agent_risk("Net_Exec", 50, false), 2) }

@[test]
fn test_risk_critical_when_irreversible() { assert_eq(agent_risk("AI", 10, true), 3) }

@[test]
fn test_compliance_ok_within_budget() {
    let p = Policy { allowed_effects: "AI_FS", max_budget_pct: 80 }
    match check_compliance(p, "AI", 50) {
        Ok(_) => assert(true)
        Err(_) => assert(false)
    }
}

@[test]
fn test_compliance_violation_on_net() {
    let p = Policy { allowed_effects: "AI_FS", max_budget_pct: 80 }
    match check_compliance(p, "Net", 50) {
        Ok(_) => assert(false)
        Err(_) => assert(true)
    }
}

@[test]
fn test_gate_high_risk_requires_score_80() {
    assert(!gate_by_risk(2, 70))
    assert(gate_by_risk(2, 85))
}

// ── Main ─────────────────────────────────────────────────────────────────────

fn main() {
    // Scenario 1: Low-risk AI-only agent — runs fully and deploys
    println("=== Scenario 1: Low-risk AI-only agent ===")
    let risk1 = agent_risk("AI", 20, false)
    println("Risk: {risk_name(risk1)} (level {to_str(risk1)})")
    let policy1 = Policy { allowed_effects: "AI", max_budget_pct: 90 }
    match run_monitored(policy1, 100) {
        Ok(best) => {
            println("Best score: {to_str(best)}")
            let deployed = gate_by_risk(risk1, best)
            println("Deployed: {to_str_bool(deployed)}")
        }
        Err(e) => println("Halted: {e}")
    }

    // Scenario 2: High-risk Net+Exec agent — full pipeline gate required
    println("")
    println("=== Scenario 2: High-risk Net+Exec agent ===")
    let risk2 = agent_risk("Net_Exec", 50, false)
    println("Risk: {risk_name(risk2)} (level {to_str(risk2)})")
    println("Full pipeline required: {to_str_bool(risk2 >= 2)}")
    let score2 = 85
    let deployed2 = gate_by_risk(risk2, score2)
    println("Score: {to_str(score2)} → Deployed: {to_str_bool(deployed2)}")

    // Scenario 3: Budget-exceeded → compliance violation → self-halt
    println("")
    println("=== Scenario 3: Budget-limited agent (self-halt on violation) ===")
    let risk3 = agent_risk("AI", 30, false)
    println("Risk: {risk_name(risk3)} (level {to_str(risk3)})")
    // total_budget=50, cost=10/iter, max_budget_pct=55%:
    //   iter 0: 10/50 = 20% ok  iter 1: 40% ok  iter 2: 60% > 55% → violation
    let policy3 = Policy { allowed_effects: "AI", max_budget_pct: 55 }
    match run_monitored(policy3, 50) {
        Ok(best) => println("Completed, best score: {to_str(best)}")
        Err(e) => println("Self-halted: {e}")
    }
}

@[test]
fn test_agent_risk_irreversible_dominates() {
    assert_eq(agent_risk("Net_Exec", 100, true), 3)
    assert_eq(agent_risk("Net", 0, true), 3)
    assert_eq(agent_risk("Exec", 95, true), 3)
}

@[test]
fn test_agent_risk_budget_burn_threshold() {
    assert_eq(agent_risk("AI", 80, false), 0)
    assert_eq(agent_risk("AI", 81, false), 2)
    assert_eq(agent_risk("Net", 80, false), 1)
    assert_eq(agent_risk("Net", 81, false), 2)
    assert_eq(agent_risk("Exec", 100, false), 2)
}

@[test]
fn test_agent_risk_by_effect_set() {
    assert_eq(agent_risk("AI", 0, false), 0)
    assert_eq(agent_risk("Net", 50, false), 1)
    assert_eq(agent_risk("Exec", 50, false), 1)
    assert_eq(agent_risk("Net_Exec", 0, false), 2)
    assert_eq(agent_risk("FS", 10, false), 0)
}

@[test]
fn test_risk_name_levels() {
    assert(risk_name(0) == "Low")
    assert(risk_name(1) == "Medium")
    assert(risk_name(2) == "High")
    assert(risk_name(3) == "Critical")
}

@[test]
fn test_risk_name_out_of_range() {
    assert(risk_name(-1) == "Low")
    assert(risk_name(4) == "Critical")
    assert(risk_name(99) == "Critical")
}

@[test]
fn test_risk_name_of_agent_risk() {
    assert(risk_name(agent_risk("AI", 20, false)) == "Low")
    assert(risk_name(agent_risk("Net", 20, false)) == "Medium")
    assert(risk_name(agent_risk("Net_Exec", 50, false)) == "High")
    assert(risk_name(agent_risk("AI", 10, true)) == "Critical")
}

@[test]
fn test_check_compliance_budget_boundary() {
    let p = Policy { allowed_effects: "AI", max_budget_pct: 80 }
    match check_compliance(p, "AI", 80) {
        Ok(s) => assert(s == "compliant")
        Err(_) => assert(false)
    }
    match check_compliance(p, "AI", 81) {
        Ok(_) => assert(false)
        Err(e) => assert(e == "budget exceeded: 81% > 80%")
    }
    match check_compliance(p, "AI", 0) {
        Ok(s) => assert(s == "compliant")
        Err(_) => assert(false)
    }
}

@[test]
fn test_check_compliance_effect_allowlist() {
    let narrow = Policy { allowed_effects: "AI", max_budget_pct: 90 }
    let wide = Policy { allowed_effects: "AI_Net_Exec", max_budget_pct: 90 }
    match check_compliance(narrow, "Net", 10) {
        Ok(_) => assert(false)
        Err(e) => assert(e == "effect denied: Net not in allowed_effects=AI")
    }
    match check_compliance(narrow, "Exec", 10) {
        Ok(_) => assert(false)
        Err(e) => assert(e == "effect denied: Exec not in allowed_effects")
    }
    match check_compliance(wide, "Net", 10) {
        Ok(s) => assert(s == "compliant")
        Err(_) => assert(false)
    }
    match check_compliance(wide, "Exec", 10) {
        Ok(s) => assert(s == "compliant")
        Err(_) => assert(false)
    }
}

@[test]
fn test_check_compliance_budget_checked_before_effects() {
    let p = Policy { allowed_effects: "AI", max_budget_pct: 55 }
    match check_compliance(p, "Net", 60) {
        Ok(_) => assert(false)
        Err(e) => assert(e == "budget exceeded: 60% > 55%")
    }
    match check_compliance(p, "AI", 40) {
        Ok(s) => assert(s == "compliant")
        Err(_) => assert(false)
    }
}

@[test]
fn test_score_work_linear_low_effort() {
    assert_eq(score_work(0), 0)
    assert_eq(score_work(1), 9)
    assert_eq(score_work(5), 45)
    assert_eq(score_work(9), 81)
}

@[test]
fn test_score_work_mid_and_plateau() {
    assert_eq(score_work(10), 90)
    assert_eq(score_work(11), 90)
    assert_eq(score_work(12), 91)
    assert_eq(score_work(15), 92)
    assert_eq(score_work(19), 94)
    assert_eq(score_work(20), 95)
    assert_eq(score_work(500), 95)
}

@[test]
fn test_score_work_monitored_schedule() {
    // run_monitored uses effort = iteration * 5 for iterations 0..4
    assert_eq(score_work(0 * 5), 0)
    assert_eq(score_work(1 * 5), 45)
    assert_eq(score_work(2 * 5), 90)
    assert_eq(score_work(3 * 5), 92)
    assert_eq(score_work(4 * 5), 95)
}

// Axon ASI demo (cousin #3): summarizer with length-vs-quality tradeoff.
//
// Demonstrates a **composite metric** (correctness + brevity) without
// reward-shaping syntax (F10 in ROADMAP §9.5).  We hand-compute the
// composite score in score_variant; once Phase 8 lands, this becomes
// `@[reward(weight: ...)]` annotations on each component.
//
// Goal: find a summarization prompt whose summaries are (a) short
// (≤ 12 words) and (b) capture the key concept (validated by a second
// LLM call that returns Uncertain<i64> confidence in coverage).
//
// Run: ANTHROPIC_API_KEY=... axon run examples/asi/summarize.ax

// ── Test set: 3 source paragraphs + their key concept ──────────────────────

fn source_text(i: i64) -> str {
    if i == 0 {
        "The Anthropic API supports prompt caching, which dramatically reduces cost for repeated context. Caches expire after five minutes by default."
    } else if i == 1 {
        "LLVM 17 introduces opaque pointers throughout its IR, simplifying type management and enabling further optimizer passes that were previously blocked by typed pointers."
    } else if i == 2 {
        "Rust's borrow checker prevents data races at compile time by enforcing that mutable references are never aliased with any other reference, mutable or shared."
    } else {
        ""
    }
}

fn key_concept(i: i64) -> str {
    if i == 0 { "prompt caching reduces API cost" }
    else if i == 1 { "LLVM 17 uses opaque pointers" }
    else if i == 2 { "Rust prevents data races at compile time" }
    else { "" }
}

// ── Prompt variants — vary terseness pressure ──────────────────────────────

fn build_prompt(variant_id: i64) -> str {
    let v = variant_id % 5
    let v2 = if v < 0 { v + 5 } else { v }
    if v2 == 0 {
        "Summarize in one short sentence (≤ 12 words). Output the summary only, no preamble. Text: "
    } else if v2 == 1 {
        "Compress to a single short sentence. Be terse. Text: "
    } else if v2 == 2 {
        "Output a one-sentence summary. Text: "
    } else if v2 == 3 {
        "TASK: 12-word-or-fewer summary. Output only the summary. Text: "
    } else {
        "Summarize tersely (≤ 12 words). Text: "
    }
}

// ── Scoring helpers ─────────────────────────────────────────────────────────
// Word count: count spaces + 1 (rough but stable for short outputs).

fn word_count(s: str) -> i64 {
    let n = str_len(s)
    let count = 0
    let i = 0
    while i < n {
        if char_at(s, i) == 32 {
            count = count + 1
        }
        i = i + 1
    }
    count + 1
}

// Length score: 12 points when ≤ 12 words, decays linearly.
fn length_score(words: i64) -> i64 {
    if words <= 12 {
        12
    } else if words >= 30 {
        0
    } else {
        12 - (words - 12)
    }
}

// Coverage score: ask the LLM "did the summary capture <concept>?".
// Returns 0..21 (Uncertain<i64> 0/1 × 0..21 confidence-weighted).

fn coverage_score(summary: str, concept: str) -> i64 {
    let q = "Does the following summary capture this key idea: '{concept}'? Output 1 for yes, 0 for no. Summary: {summary}"
    match ai_extract_uncertain_i64(q) {
        Ok(u) => {
            let correct_f = if u.value == 1 { 21.0 } else { 0.0 }
            f64_to_i64(u.confidence * correct_f)
        }
        Err(_) => 0
    }
}

// ── Score one sample (composite: length × coverage) ────────────────────────

fn score_one(prefix: str, idx: i64) -> i64 {
    let prompt = "{prefix}{source_text(idx)}"
    match ai_complete(prompt) {
        Ok(summary) => {
            let words = word_count(summary)
            let length = length_score(words)
            let coverage = coverage_score(summary, key_concept(idx))
            length + coverage
        }
        Err(_) => 0
    }
}

fn score_variant(variant_id: i64) -> i64 {
    let prefix = build_prompt(variant_id)
    let s0 = score_one(prefix, 0)
    let s1 = score_one(prefix, 1)
    let s2 = score_one(prefix, 2)
    s0 + s1 + s2
}

@[adaptive(metric: summary_quality, target: 99)]
fn try_variant(variant_id: i64) -> i64 {
    score_variant(variant_id)
}

@[verify(confidence >= 0.85)]
fn deploy_gate(best_score: f64) -> Uncertain<i64> {
    let conf = best_score / 99.0
    let clamped = if best_score < 0.0 { 0.0 }
                  else if best_score > 99.0 { 99.0 }
                  else { best_score }
    uncertain_dyn_i64(f64_to_i64(clamped), conf)
}

fn main() -> i64 {
    println("=== Axon ASI demo (cousin #3): summarizer ===")
    println("Composite metric: length (≤12 words) + coverage (LLM-judged)")
    println("Search space: 5 prompt variants")
    println("")

    let _ = try_variant(0)
    let best = goal_run("try_variant", 99.0, 15)
    println("Best observed score: {to_str_f64(best)} / 99")

    let u = deploy_gate(best)
    println("Deploy gate: PASS — confidence >= 0.85")
    println("Confirmed best score: {to_str(u.value)}")
    0
}

