    let eg = match check_field(empty, "goal") { Ok(v) => "OK {v}"  Err(e) => "ERR {e}" }
    let ec = match check_field(empty, "constraints") { Ok(v) => "OK {v}"  Err(e) => "ERR {e}" }
    assert(eg == "ERR field 'goal' is too short (< 5 chars)")
    assert(ec == "OK valid constraint")
