fn test_merge_contained_and_empty() {
    let m = merge(&[Iv { lo: 1, hi: 10 }, Iv { lo: 2, hi: 3 }, Iv { lo: 4, hi: 5 }])
    assert_eq(len(m), 1)
    assert_eq(m[0].hi, 10)
    let e = merge(&[Iv { lo: 3, hi: 3 }, Iv { lo: 5, hi: 4 }])
    assert_eq(len(e), 0)
}

@[test]
fn test_covered_length() {
    assert_eq(covered_length(&[Iv { lo: 1, hi: 3 }, Iv { lo: 2, hi: 6 }, Iv { lo: 8, hi: 10 }]), 7)
    assert_eq(covered_length(&[Iv { lo: 0, hi: 5 }, Iv { lo: 5, hi: 9 }]), 9)
    assert_eq(covered_length(&[Iv { lo: 2, hi: 12 }, Iv { lo: 4, hi: 6 }]), 10)
}

@[test]
fn test_max_overlap_nested() {
    assert_eq(max_overlap(&[Iv { lo: 0, hi: 10 }, Iv { lo: 1, hi: 2 }, Iv { lo: 3, hi: 4 }]), 2)
    assert_eq(max_overlap(&[Iv { lo: 0, hi: 10 }, Iv { lo: 1, hi: 9 }, Iv { lo: 2, hi: 8 }]), 3)
}

@[test]
fn test_max_overlap_touching() {
    assert_eq(max_overlap(&[Iv { lo: 0, hi: 5 }, Iv { lo: 5, hi: 9 }]), 1)
    assert_eq(max_overlap(&[Iv { lo: 1, hi: 3 }, Iv { lo: 3, hi: 4 }, Iv { lo: 4, hi: 6 }]), 1)
}

@[test]
fn test_max_overlap_meetings() {
    let day = [Iv { lo: 9, hi: 10 }, Iv { lo: 9, hi: 12 }, Iv { lo: 11, hi: 13 }, Iv { lo: 10, hi: 11 }, Iv { lo: 12, hi: 14 }, Iv { lo: 9, hi: 14 }]
    assert_eq(max_overlap(&day), 3)
    assert_eq(max_overlap(&[Iv { lo: 1, hi: 4 }, Iv { lo: 2, hi: 3 }, Iv { lo: 5, hi: 8 }, Iv { lo: 6, hi: 7 }]), 2)
}

@[test]
fn test_first_free() {
    let busy = [Iv { lo: 9, hi: 10 }, Iv { lo: 10, hi: 12 }, Iv { lo: 13, hi: 15 }]
    assert_eq(first_free(&busy, 9, 1), 12)
    assert_eq(first_free(&busy, 9, 2), 15)
    assert_eq(first_free(&busy, 8, 1), 8)
    assert_eq(first_free(&busy, 12, 1), 12)
}

// scheduler.ax — CPU-scheduling estimates for a job dashboard.
//
// Every job arrives at time 0; `bursts[i]` is job i's run time. A job with a
// burst of 0 completes at time 0. "Completion time" is when the job's last
// unit of work finishes.
//
//   axon test scheduler.ax

// First-come-first-served: jobs run to completion in index order.
fn fcfs_finish(bursts: &[i64], job: i64) -> i64 {
    let t = 0
    for i in 0..job + 1 {
        t = t + bursts[i]
    }
    t
}

// Shortest-job-first, non-preemptive: jobs run to completion in order of
// burst, ties broken by the lower index.
fn sjf_finish(bursts: &[i64], job: i64) -> i64 {
    let t = 0
    for i in 0..len(bursts) {
        if bursts[i] < bursts[job] || (bursts[i] == bursts[job] && i <= job) {
            t = t + bursts[i]
        }
    }
    t
}

// Round robin with time slice `quantum`: the ready queue starts in index
// order; the job at the head runs for min(quantum, remaining) and, if it is
// not finished, goes to the back of the queue. Returns job `job`'s completion
// time.
fn round_robin_finish(bursts: &[i64], quantum: i64, job: i64) -> i64 {
    if bursts[job] == 0 {
        return 0
    }
    let rem = []
    for i in 0..len(bursts) {
        rem = arr_push(rem, bursts[i])
    }
    let t = 0
    while true {
        for i in 0..len(rem) {
            if rem[i] > 0 {
                let run = min_i64(quantum, rem[i])
                t = t + run
                rem[i] = rem[i] - run
                if rem[i] == 0 && i == job {
                    return t
                }
            }
        }
    }
    t
}

@[test]
fn test_fcfs() {
    assert_eq(fcfs_finish(&[3, 4, 5], 0), 3)
    assert_eq(fcfs_finish(&[3, 4, 5], 2), 12)
}

@[test]
fn test_sjf() {
    assert_eq(sjf_finish(&[6, 2, 8, 3], 0), 11)
    assert_eq(sjf_finish(&[6, 2, 8, 3], 2), 19)
    assert_eq(sjf_finish(&[4, 4, 1], 1), 9)
}

@[test]
fn test_rr_trivial() {
    assert_eq(round_robin_finish(&[5], 2, 0), 5)
    assert_eq(round_robin_finish(&[0, 4], 2, 0), 0)
    assert_eq(round_robin_finish(&[0, 4], 2, 1), 4)
}

@[test]
fn test_rr_quantum_two() {
    assert_eq(round_robin_finish(&[5, 3, 1], 2, 0), 9)
    assert_eq(round_robin_finish(&[5, 3, 1], 2, 1), 8)
    assert_eq(round_robin_finish(&[5, 3, 1], 2, 2), 5)
    assert_eq(round_robin_finish(&[1, 8, 3, 5], 2, 0), 1)
    assert_eq(round_robin_finish(&[1, 8, 3, 5], 2, 3), 15)
}

@[test]
fn test_rr_larger_quanta() {
    assert_eq(round_robin_finish(&[10, 4, 7, 2], 3, 1), 15)
    assert_eq(round_robin_finish(&[10, 4, 7, 2], 3, 2), 22)
    assert_eq(round_robin_finish(&[10, 4, 7, 2], 3, 3), 11)
    assert_eq(round_robin_finish(&[6, 6, 6], 4, 0), 14)
    assert_eq(round_robin_finish(&[2, 3], 5, 0), 2)
}

// semver.ax — Semantic Versioning 2.0.0 precedence for a package resolver.
//
// A version is MAJOR.MINOR.PATCH, optionally followed by `-PRERELEASE`
// (dot-separated identifiers) and/or `+BUILD` metadata. Precedence:
//   1. MAJOR, MINOR and PATCH compare numerically, in that order.
//   2. A version with a pre-release is LOWER than the same version without.
//   3. Pre-release identifiers compare left to right: two numeric identifiers
//      compare numerically, two alphanumeric ones in ASCII order, and a numeric
//      identifier is lower than an alphanumeric one. If every identifier of the
//      shorter list equals the other's, the shorter list is lower.
//   4. Build metadata is ignored.
// So 1.0.0-alpha < 1.0.0-alpha.1 < 1.0.0-alpha.beta < 1.0.0-beta
//    < 1.0.0-beta.2 < 1.0.0-beta.11 < 1.0.0-rc.1 < 1.0.0.
//
//   axon test semver.ax

// The k-th piece of `s` split on the byte `sep`, or "" past the end.
fn piece(s: str, sep: i64, k: i64) -> str {
    let idx = 0
    let start = 0
    let n = len(s)
    for i in 0..n {
        if char_at(s, i) == sep {
            if idx == k {
                return str_slice(s, start, i)
            }
            idx = idx + 1
            start = i + 1
        }
    }
    if idx == k { str_slice(s, start, n) } else { "" }
}

// How many pieces splitting on `sep` produces.
fn piece_count(s: str, sep: i64) -> i64 {
    let n = 1
    for i in 0..len(s) {
        if char_at(s, i) == sep {
            n = n + 1
        }
    }
    n
}

fn is_numeric(s: str) -> bool {
    let ok = len(s) > 0
    for i in 0..len(s) {
        let c = char_at(s, i)
        if c < 48 || c > 57 {
            ok = false
        }
    }
    ok
}

fn num(s: str) -> i64 {
    match parse_int(s) {
        Ok(n) => n
        Err(_) => 0
    }
}

fn cmp_i64(a: i64, b: i64) -> i64 {
    if a < b { -1 } else if a > b { 1 } else { 0 }
}

// -1 if a has lower precedence than b, 1 if higher, 0 if equal.
fn compare_versions(a: str, b: str) -> i64 {
    let va = piece(a, 43, 0)
    let vb = piece(b, 43, 0)
    let core_a = piece(va, 45, 0)
    let core_b = piece(vb, 45, 0)
    let da = str_index_of(va, "-")
    let db = str_index_of(vb, "-")
    let pre_a = if da < 0 { "" } else { str_slice(va, da + 1, len(va)) }
    let pre_b = if db < 0 { "" } else { str_slice(vb, db + 1, len(vb)) }
    for k in 0..3 {
        let c = cmp_i64(num(piece(core_a, 46, k)), num(piece(core_b, 46, k)))
        if c != 0 {
            return c
        }
    }
    if pre_a == "" && pre_b == "" {
        return 0
    }
    if pre_a == "" {
        return 1
    }
    if pre_b == "" {
        return -1
    }
    let na = piece_count(pre_a, 46)
    let nb = piece_count(pre_b, 46)
    let k = 0
    while k < na && k < nb {
        let x = piece(pre_a, 46, k)
        let y = piece(pre_b, 46, k)
        let c = if is_numeric(x) && is_numeric(y) {
            cmp_i64(num(x), num(y))
        } else if is_numeric(x) {
            -1
        } else if is_numeric(y) {
            1
        } else {
            str_cmp(x, y)
        }
        if c != 0 {
            return c
        }
        k = k + 1
    }
    cmp_i64(na, nb)
}

@[test]
fn test_compare_equal_and_patch() {
    assert_eq(compare_versions("1.2.3", "1.2.3"), 0)
    assert_eq(compare_versions("1.2.3", "1.2.4"), -1)
    assert_eq(compare_versions("2.0.0", "1.9.9"), 1)
}

@[test]
fn test_compare_numeric_fields() {
    assert_eq(compare_versions("1.10.0", "1.9.0"), 1)
}

@[test]
fn test_compare_prerelease_chain() {
    assert_eq(compare_versions("1.0.0-alpha", "1.0.0-alpha.1"), -1)
    assert_eq(compare_versions("1.0.0-alpha.1", "1.0.0-alpha.beta"), -1)
    assert_eq(compare_versions("1.0.0-alpha.beta", "1.0.0-beta"), -1)
