@[test]
fn test_eval_arithmetic() {
    match eval(Expr::Add { left: 10, right: 32 }) { Ok(v) => assert_eq(v, 42), Err(_) => assert(false) }
    match eval(Expr::Sub { left: 100, right: 58 }) { Ok(v) => assert_eq(v, 42), Err(_) => assert(false) }
    match eval(Expr::Mul { left: 6, right: 7 }) { Ok(v) => assert_eq(v, 42), Err(_) => assert(false) }
}

@[test]
fn test_eval_num_and_neg() {
    match eval(Expr::Num { value: 42 }) { Ok(v) => assert_eq(v, 42), Err(_) => assert(false) }
    match eval(Expr::Neg { inner: 7 }) { Ok(v) => assert_eq(v, -7), Err(_) => assert(false) }
}

@[test]
fn test_eval_division() {
    match eval(Expr::Div { left: 84, right: 2 }) { Ok(v) => assert_eq(v, 42), Err(_) => assert(false) }
    match eval(Expr::Div { left: 1, right: 0 }) { Ok(_) => assert(false), Err(e) => assert(e == "division by zero") }
}

