    assert(show(Expr::Num { value: 42 }) == "42")
    assert(show(Expr::Neg { inner: 7 }) == "-(7)")
    assert(show(Expr::Add { left: 10, right: 32 }) == "10 + 32")
    assert(show(Expr::Div { left: 84, right: 2 }) == "84 / 2")
}

