// Tier-1 stdlib: Distribution — userland wrappers over the Phase-13 distribution builtins.
//
// Three tractable distribution families with validated constructors, pure query
// functions, and impure sampling functions (effect row: Random).
//
// Distribution builtins are defined in spec/compiler-phase13.md §2.  This file
// provides the recommended userland interface — callers should use these structs
// and helpers rather than calling the raw builtins directly.
//
//   axon test examples/stdlib/distribution.ax   # run the @[test]s
//   axon run  examples/stdlib/distribution.ax   # demo

// ── Struct types ──────────────────────────────────────────────────────────────

type Gaussian    = { mu: f64, sigma: f64 }
type Beta        = { alpha: f64, beta_b: f64 }
type Categorical = { probs: [f64] }

// ── Helpers ───────────────────────────────────────────────────────────────────

// Approximate equality within a tolerance — used in tests to compare f64 values.
fn approx_eq(a: f64, b: f64, tol: f64) -> bool {
    let diff = a - b
    diff >= -tol && diff <= tol
}

// Sum a [f64] array.  Wraps arr_sum_f64 for brevity.
fn sum_f64_arr(xs: [f64]) -> f64 {
    arr_sum_f64(xs)
}

// ── Gaussian constructors and queries ─────────────────────────────────────────

// Construct a Gaussian distribution.  Panics if sigma <= 0.0.
fn gaussian_new(mu: f64, sigma: f64) -> Gaussian {
    if sigma <= 0.0 {
        println("gaussian_new: sigma must be > 0.0")
        assert(false)
    }
    Gaussian { mu: mu, sigma: sigma }
}

// Mean of the distribution.
fn gaussian_mean(g: Gaussian) -> f64 {
    g.mu
}

// Standard deviation of the distribution.
fn gaussian_std(g: Gaussian) -> f64 {
    g.sigma
}

// P(X <= x) for this Gaussian — delegates to gaussian_cdf.
fn gaussian_prob_lte(g: Gaussian, x: f64) -> f64 {
    gaussian_cdf(g.mu, g.sigma, x)
}

// Probability density at x — delegates to gaussian_pdf.
fn gaussian_density(g: Gaussian, x: f64) -> f64 {
    gaussian_pdf(g.mu, g.sigma, x)
}

// ── Beta constructors and queries ─────────────────────────────────────────────

// Construct a Beta distribution.  Panics if alpha <= 0.0 or beta_b <= 0.0.
fn beta_new(alpha: f64, beta_b: f64) -> Beta {
    if alpha <= 0.0 {
        println("beta_new: alpha must be > 0.0")
        assert(false)
    }
    if beta_b <= 0.0 {
        println("beta_new: beta_b must be > 0.0")
        assert(false)
    }
    Beta { alpha: alpha, beta_b: beta_b }
}

// Mean (expected value) of the Beta distribution.
fn beta_mu(b: Beta) -> f64 {
    beta_mean(b.alpha, b.beta_b)
}

// Variance of the Beta distribution.
fn beta_sigma2(b: Beta) -> f64 {
    beta_variance(b.alpha, b.beta_b)
}

// P(X <= x) for this Beta distribution.
fn beta_prob_lte(b: Beta, x: f64) -> f64 {
    beta_cdf(b.alpha, b.beta_b, x)
}

// ── Categorical constructors and queries ──────────────────────────────────────

// Construct a Categorical distribution.
// Panics if probs is empty or if the sum of probs is not within 0.001 of 1.0.
fn categorical_new(probs: [f64]) -> Categorical {
    if len(probs) == 0 {
        println("categorical_new: probs must not be empty")
        assert(false)
    }
    let s = sum_f64_arr(probs)
    let diff = s - 1.0
    let ok = diff >= -0.001 && diff <= 0.001
    if !ok {
        println("categorical_new: probs must sum to 1.0 (within 0.001)")
        assert(false)
    }
    Categorical { probs: probs }
}

// Mean (expected value) of the Categorical distribution.
fn categorical_mu(c: Categorical) -> f64 {
    categorical_mean(c.probs)
}

// Variance of the Categorical distribution.
fn categorical_sigma2(c: Categorical) -> f64 {
    categorical_variance(c.probs)
}

// P(X <= k) for this Categorical distribution.
fn categorical_prob_lte(c: Categorical, k: i64) -> f64 {
    categorical_cdf(c.probs, k)
}

// ── Sampling functions (effect row: Random) ───────────────────────────────────

// Draw one sample from the Gaussian.  Non-deterministic; use AXON_SEED for replay.
fn dist_sample_gaussian(g: Gaussian) -> f64 {
    gaussian_sample(g.mu, g.sigma)
}

// Draw one sample from the Beta distribution.  Returns a value in [0.0, 1.0].
fn dist_sample_beta(b: Beta) -> f64 {
    beta_sample(b.alpha, b.beta_b)
}

// Draw one index from the Categorical distribution.  Returns a value in [0, len(probs)).
fn dist_sample_categorical(c: Categorical) -> i64 {
    categorical_sample(c.probs)
}

// ── Tests ─────────────────────────────────────────────────────────────────────

// The constructors validate by `assert(false)`, and none of those guards had a
// test: a mutation sweep flipped every `if sigma <= 0.0` / `alpha <= 0.0` /
// `len(probs) == 0` / `!ok` to `false` and all five mutants survived. A
// constructor that accepts a negative sigma produces a distribution whose CDF
// and sampler are meaningless, silently.

@[test(should_fail)]
fn test_gaussian_rejects_zero_sigma() { let _g = gaussian_new(0.0, 0.0) }

@[test(should_fail)]
fn test_gaussian_rejects_negative_sigma() { let _g = gaussian_new(1.0, -2.0) }

@[test(should_fail)]
fn test_beta_rejects_nonpositive_alpha() { let _b = beta_new(0.0, 1.0) }

@[test(should_fail)]
fn test_beta_rejects_nonpositive_beta() { let _b = beta_new(1.0, -1.0) }

@[test(should_fail)]
fn test_categorical_rejects_empty_probs() { let _c = categorical_new([]) }

@[test(should_fail)]
fn test_categorical_rejects_probs_that_do_not_sum_to_one() {
    let _c = categorical_new([0.2, 0.2])
}

@[test]
fn test_gaussian_mean_and_std() {
    let g = gaussian_new(3.5, 1.2)
    assert(approx_eq(gaussian_mean(g), 3.5, 0.0001))
    assert(approx_eq(gaussian_std(g), 1.2, 0.0001))
}

@[test]
fn test_gaussian_prob_lte_standard_normal_at_zero() {
    // P(X <= 0) for the standard normal is exactly 0.5.
    let g = gaussian_new(0.0, 1.0)
    assert(approx_eq(gaussian_prob_lte(g, 0.0), 0.5, 0.001))
}

@[test]
fn test_gaussian_density_standard_normal_at_zero() {
    // The standard-normal PDF at 0 is 1/sqrt(2*pi) ≈ 0.39894.
    let g = gaussian_new(0.0, 1.0)
    assert(approx_eq(gaussian_density(g, 0.0), 0.39894, 0.0001))
}

@[test]
fn test_gaussian_cdf_shifts_with_mu() {
    // P(X <= mu) = 0.5 regardless of mu (by symmetry).
    let g = gaussian_new(10.0, 2.0)
    assert(approx_eq(gaussian_prob_lte(g, 10.0), 0.5, 0.001))
}

@[test]
fn test_beta_mu_uniform() {
    // E[Beta(1, 1)] = 1/(1+1) = 0.5.
    let b = beta_new(1.0, 1.0)
    assert(approx_eq(beta_mu(b), 0.5, 0.0001))
}

@[test]
fn test_beta_mu_asymmetric() {
    // E[Beta(2, 8)] = 2/10 = 0.2.
    let b = beta_new(2.0, 8.0)
    assert(approx_eq(beta_mu(b), 0.2, 0.0001))
}

@[test]
fn test_beta_variance() {
    // Var[Beta(2, 2)] = (2*2)/((4)^2 * 5) = 4/80 = 0.05.
    let b = beta_new(2.0, 2.0)
    assert(approx_eq(beta_sigma2(b), 0.05, 0.0001))
}

@[test]
fn test_beta_cdf_uniform_at_half() {
    // Beta(1,1) is Uniform[0,1]; P(X <= 0.5) = 0.5.
    let b = beta_new(1.0, 1.0)
    assert(approx_eq(beta_prob_lte(b, 0.5), 0.5, 0.001))
}

@[test]
fn test_beta_cdf_boundary() {
    let b = beta_new(2.0, 3.0)
    // P(X <= 0.0) = 0.0 and P(X <= 1.0) = 1.0.
    assert(approx_eq(beta_prob_lte(b, 0.0), 0.0, 0.0001))
    assert(approx_eq(beta_prob_lte(b, 1.0), 1.0, 0.0001))
}

@[test]
fn test_categorical_mu_uniform() {
    // Four equally likely outcomes {0, 1, 2, 3}: E[X] = (0+1+2+3)/4 = 1.5.
    let c = categorical_new([0.25, 0.25, 0.25, 0.25])
    assert(approx_eq(categorical_mu(c), 1.5, 0.0001))
}

@[test]
fn test_categorical_mu_degenerate() {
    // Degenerate distribution: P(X=2) = 1.  E[X] = 2.0.
    let c = categorical_new([0.0, 0.0, 1.0])
    assert(approx_eq(categorical_mu(c), 2.0, 0.0001))
}

@[test]
fn test_categorical_cdf_is_cumulative() {
    // probs = [0.1, 0.4, 0.3, 0.2].
    // P(X <= 0) = 0.1, P(X <= 1) = 0.5, P(X <= 2) = 0.8, P(X <= 3) = 1.0.
    let c = categorical_new([0.1, 0.4, 0.3, 0.2])
    assert(approx_eq(categorical_prob_lte(c, 0), 0.1, 0.0001))
    assert(approx_eq(categorical_prob_lte(c, 1), 0.5, 0.0001))
    assert(approx_eq(categorical_prob_lte(c, 2), 0.8, 0.0001))
    assert(approx_eq(categorical_prob_lte(c, 3), 1.0, 0.0001))
}

@[test]
fn test_categorical_cdf_out_of_range() {
    // P(X <= -1) = 0.0; P(X <= 99) = 1.0.
    let c = categorical_new([0.3, 0.7])
    assert(approx_eq(categorical_prob_lte(c, -1), 0.0, 0.0001))
    assert(approx_eq(categorical_prob_lte(c, 99), 1.0, 0.0001))
}

@[test]
fn test_gaussian_sample_is_a_finite_real() {
    // `gaussian_sample` executed NOWHERE: its only wrapper, dist_sample_gaussian,
    // had zero callers repo-wide, while both sibling wrappers were tested. A
    // mutation making the builtin panic on call survived the whole suite.
    //
    // A Gaussian is unbounded, so there is no value range to assert. The total
    // property is FINITENESS: `s - s == 0.0` is true for every real and false
    // for both non-finite results — inf - inf is NaN, and NaN != 0.0. Asserted
    // rather than a range so this can never be flaky; a range test on an
    // unbounded distribution is a coin toss with long odds, not a test.
    let g = gaussian_new(10.0, 2.0)
    let s = dist_sample_gaussian(g)
    assert(s - s == 0.0)
}

@[test]
fn test_beta_sample_is_in_unit_interval() {
    // beta_sample returns values in [0.0, 1.0].
    let b = beta_new(1.0, 1.0)
    let s = dist_sample_beta(b)
    assert(s >= 0.0 && s <= 1.0)
}

@[test]
fn test_categorical_sample_degenerate_always_returns_one() {
    // P(X=1) = 1.0 — sampling must always yield 1.
    let c = categorical_new([0.0, 1.0])
    let s = dist_sample_categorical(c)
    assert_eq(s, 1)
}

// ── Phase 13 Slice 2: E[dist], Var[dist], P(dist op k) predicate tests ────────

@[test]
fn test_gaussian_E_moment_predicate() {
    // E[Gaussian(2.0, 1.0)] should be 2.0.
    let g = gaussian_new(2.0, 1.0)
    let mean = E[g]
    assert(approx_eq(mean, 2.0, 0.0001))
}

@[test]
fn test_gaussian_Var_moment_predicate() {
    // Var[Gaussian(0.0, 3.0)] should be 9.0.
    let g = gaussian_new(0.0, 3.0)
    let v = Var[g]
    assert(approx_eq(v, 9.0, 0.0001))
}

@[test]
fn test_beta_E_moment_predicate() {
    // E[Beta(2, 5)] = 2/7 ≈ 0.2857.
    let b = beta_new(2.0, 5.0)
    let mean = E[b]
    assert(approx_eq(mean, 2.0 / 7.0, 0.0001))
}

@[test]
fn test_beta_Var_moment_predicate() {
    // Var[Beta(2, 5)] = (2*5)/((7^2)*(8)) = 10/392 ≈ 0.02551.
    let b = beta_new(2.0, 5.0)
    let v = Var[b]
    assert(approx_eq(v, 10.0 / 392.0, 0.0001))
}

@[test]
fn test_categorical_E_moment_predicate() {
    // probs = [0.2, 0.5, 0.3]; E[X] = 0*0.2 + 1*0.5 + 2*0.3 = 1.1.
    let c = categorical_new([0.2, 0.5, 0.3])
    let mean = E[c]
    assert(approx_eq(mean, 1.1, 0.0001))
}

@[test]
fn test_categorical_Var_moment_predicate() {
    // probs = [0.5, 0.5]; E=0.5, E[X^2]=0*0.5+1*0.5=0.5, Var=0.5-0.25=0.25.
    let c = categorical_new([0.5, 0.5])
    let v = Var[c]
    assert(approx_eq(v, 0.25, 0.0001))
}

@[test]
fn test_gaussian_P_cdf_predicate_lte() {
    // P(Gaussian(0, 1) <= 0) ≈ 0.5.
    let g = gaussian_new(0.0, 1.0)
    let prob = P(g <= 0.0)
    assert(approx_eq(prob, 0.5, 0.001))
}

@[test]
fn test_gaussian_P_cdf_predicate_gt() {
    // P(Gaussian(0, 1) > 0) ≈ 0.5.
    let g = gaussian_new(0.0, 1.0)
    let prob = P(g > 0.0)
    assert(approx_eq(prob, 0.5, 0.001))
}

@[test]
fn test_beta_P_cdf_predicate() {
    // P(Beta(1, 1) <= 0.5) = 0.5 (uniform on [0,1]).
    let b = beta_new(1.0, 1.0)
    let prob = P(b <= 0.5)
    assert(approx_eq(prob, 0.5, 0.001))
}

@[test]
fn test_categorical_P_cdf_predicate() {
    // P(Categorical([0.1, 0.4, 0.5]) <= 1) = 0.1 + 0.4 = 0.5.
    let c = categorical_new([0.1, 0.4, 0.5])
    let prob = P(c <= 1)
    assert(approx_eq(prob, 0.5, 0.0001))
}

@[test]
fn test_prob_predicate_composable_in_condition() {
    // Combining E[dist] and P(dist op k) in a conditional.
    let g = gaussian_new(0.0, 1.0)
    let low_mean = E[g] < 1.0
    let sym_tail = P(g > 2.0) < 0.1
    assert(low_mean && sym_tail)
}

fn main() -> i64 {
    // Demo: moments and a sample for each distribution family.
    let g = gaussian_new(0.0, 1.0)
    println("Gaussian(0, 1): mean={to_str_f64(gaussian_mean(g))}, std={to_str_f64(gaussian_std(g))}")
    println("  P(X <= 0)     = {to_str_f64(gaussian_prob_lte(g, 0.0))}  (expect ≈0.5)")
    println("  PDF at 0      = {to_str_f64(gaussian_density(g, 0.0))}  (expect ≈0.3989)")

    let b = beta_new(2.0, 5.0)
    println("Beta(2, 5):   mean={to_str_f64(beta_mu(b))}, var={to_str_f64(beta_sigma2(b))}")
    println("  P(X <= 0.5)   = {to_str_f64(beta_prob_lte(b, 0.5))}")
    let bs = dist_sample_beta(b)
    println("  sample        = {to_str_f64(bs)}  (in [0,1])")

    let c = categorical_new([0.1, 0.4, 0.3, 0.2])
    println("Categorical([0.1,0.4,0.3,0.2]): mean={to_str_f64(categorical_mu(c))}, var={to_str_f64(categorical_sigma2(c))}")
    println("  P(X <= 1)     = {to_str_f64(categorical_prob_lte(c, 1))}  (expect 0.5)")
    let cs = dist_sample_categorical(c)
    println("  sample        = {to_str(cs)}  (in {{0,1,2,3}})")
    0
}

sources.examples/stdlib/effect.ax:
// Tier-1 stdlib: Effect / Tool — row-polymorphic effect tracking.
//
// ROADMAP §6 Tier-1 types `Effect` ("row-polymorphic effect tag") and `Tool`
// ("typed callable with effect signature"). The full version is row-polymorphic
// effects + handlers (Phase 6, `spec/compiler-phase6.md`); this is the
// value-level core: an EFFECT SET (which of fs:read/fs:write/net/exec a piece of
// code performs) with the row operations that make effects composable —
//
//   • a function that calls two tools performs the UNION of their effects
//     (effect rows ADD — the "row-polymorphic" part: extend a row with more
//     effects),
//   • a `@[contained]` boundary admits a tool iff the tool's effect set is a
//     SUBSET of the granted ceiling (no effect outside the allowlist),
//   • PURE code has the empty effect set — the identity for union, and trivially
//     a subset of any ceiling.
//
// The effect set is a 4-bit BITSET over the capability taxonomy (the same
// fs:read/fs:write/net/exec single-sourced in capabilities.rs). A Tool is a
// named callable carrying its effect signature.
//
//   axon test examples/stdlib/effect.ax
//   axon run  examples/stdlib/effect.ax

// Single-effect bits (powers of two).
fn ef_fs_read() -> i64 { 1 }
fn ef_fs_write() -> i64 { 2 }
fn ef_net() -> i64 { 4 }
fn ef_exec() -> i64 { 8 }

// The empty effect set — PURE code. Identity for union.
fn ef_pure() -> i64 { 0 }

// Add an effect to a set (idempotent — adding a present effect is a no-op).
fn ef_add(set: i64, e: i64) -> i64 {
    bit_or(set, e)
}

// Does the set perform effect `e`?
fn ef_has(set: i64, e: i64) -> bool {
    bit_and(set, e) != 0
}

// UNION — a path that runs both performs every effect of either (effect rows
// extend). This is the row-combine the "row-polymorphic" name refers to.
fn ef_union(a: i64, b: i64) -> i64 {
    bit_or(a, b)
}

// Is `set` a SUBSET of `ceiling` — i.e. every effect in `set` is granted? This is
// the `@[contained]` admission rule at the value level: a tool whose effects all
// fall within the ceiling is admissible; one with any extra effect is rejected.
fn ef_subset(set: i64, ceiling: i64) -> bool {
    // set ⊆ ceiling  iff  set has no bit outside ceiling  iff  set & ~ceiling == 0.
    bit_and(set, bit_not(ceiling)) == 0
}

// Is this code PURE (no effects)?
fn ef_is_pure(set: i64) -> bool {
    set == ef_pure()
}

// ── Tool: a named callable carrying its effect signature ────────────────────

type Tool = {
    name: str,
    effects: i64,   // the effect set this tool performs
}

fn tool_new(name: str, effects: i64) -> Tool {
    Tool { name: name, effects: effects }
}

// May this tool run under a `@[contained]` boundary granting `ceiling`? Yes iff
// its effect signature is a subset of the granted effects.
fn tool_admissible(t: Tool, ceiling: i64) -> bool {
    ef_subset(t.effects, ceiling)
}

// The combined effect signature of a function that calls BOTH tools — the union
// (the caller inherits every effect of its callees, the transitive-effect rule).
fn tool_compose_effects(a: Tool, b: Tool) -> i64 {
    ef_union(a.effects, b.effects)
}

@[test]
fn test_pure_is_identity_and_subset_of_all() {
    assert(ef_is_pure(ef_pure()))
    assert_eq(ef_union(ef_pure(), ef_net()), ef_net())
    // Pure is a subset of any ceiling, even the empty one.
    assert(ef_subset(ef_pure(), ef_pure()))
    assert(ef_subset(ef_pure(), ef_union(ef_net(), ef_exec())))
}

@[test]
fn test_add_and_has() {
    let s = ef_add(ef_add(ef_pure(), ef_net()), ef_fs_write())
    assert(ef_has(s, ef_net()))
    assert(ef_has(s, ef_fs_write()))
    assert(!ef_has(s, ef_exec()))
    // Idempotent: adding net again doesn't change the set.
    assert_eq(ef_add(s, ef_net()), s)
}

@[test]
fn test_union_extends_the_row() {
    let reads = ef_fs_read()
    let writes_net = ef_union(ef_fs_write(), ef_net())
    let combined = ef_union(reads, writes_net)
    assert(ef_has(combined, ef_fs_read()))
    assert(ef_has(combined, ef_fs_write()))
    assert(ef_has(combined, ef_net()))
    assert(!ef_has(combined, ef_exec()))
}

@[test]
fn test_subset_is_the_admission_rule() {
    let ceiling = ef_union(ef_fs_write(), ef_net())   // grant fs:write + net
    let within = ef_net()                              // a net-only tool: admissible
    let escapes = ef_union(ef_net(), ef_exec())        // net + exec: exec is ungranted
    assert(ef_subset(within, ceiling))
    assert(!ef_subset(escapes, ceiling))
}

@[test]
fn test_tool_admissible() {
    let ceiling = ef_union(ef_fs_read(), ef_net())
    let reader = tool_new("fetch", ef_union(ef_fs_read(), ef_net()))
    let runner = tool_new("shell", ef_exec())
    assert(tool_admissible(reader, ceiling))     // reads + net ⊆ ceiling
    assert(!tool_admissible(runner, ceiling))    // exec ⊄ ceiling
}

@[test]
fn test_tool_compose_inherits_both_effects() {
    let fetch = tool_new("fetch", ef_net())
    let save = tool_new("save", ef_fs_write())
    let combined = tool_compose_effects(fetch, save)
    // A function calling both performs net AND fs:write.
    assert(ef_has(combined, ef_net()))
    assert(ef_has(combined, ef_fs_write()))
    // …and is admissible only under a ceiling granting both.
    assert(ef_subset(combined, ef_union(ef_net(), ef_fs_write())))
    assert(!ef_subset(combined, ef_net()))   // a net-only ceiling rejects it
}

fn main() {
    // A pipeline tool `fetch` (net) and `save` (fs:write); a function calling both
    // has the union effect signature. Check it against a sandbox ceiling.
    let fetch = tool_new("fetch", ef_net())
    let save = tool_new("save", ef_fs_write())
    let pipeline_effects = tool_compose_effects(fetch, save)

    let sandbox = ef_union(ef_net(), ef_fs_write())   // grant net + fs:write
    println("pipeline effects: net={to_str_bool(ef_has(pipeline_effects, ef_net()))} fs_write={to_str_bool(ef_has(pipeline_effects, ef_fs_write()))} exec={to_str_bool(ef_has(pipeline_effects, ef_exec()))}")
    if ef_subset(pipeline_effects, sandbox) {
        println("pipeline admissible under the sandbox (all effects granted) ✓")
    } else {
        println("pipeline REJECTED — performs an effect the sandbox does not grant")
    }

    // A stricter, net-only sandbox rejects the fs:write.
    if ef_subset(pipeline_effects, ef_net()) {
        println("net-only sandbox: admissible")
    } else {
        println("net-only sandbox: REJECTED — the fs:write effect escapes it")
    }
}

